source('/home/jinshengxi/bladder_metabolism/cellchat_nichechat_fibro7/scripts/common.R')
a<-readRDS(file.path(ROOT,'00_audit/major_inspection.rds'))
f<-readRDS(file.path(ROOT,'00_audit/fibro_inspection.rds'))
md<-a$metadata; fm<-f$metadata
stopifnot(all(c('orig.ident','dataset','major_celltype','cell_state','LLPS77_AUC')%in%names(md)),all(c('subcluster','clean_snn_res.0.12','source_major_celltype')%in%names(fm)))
