for(field in c('orig.ident','dataset','major_celltype','cell_state','LLPS77_AUC')) stopifnot(identical(md[[field]][j],fm[[field]]))
stopifnot(all(md$major_celltype[j]%in%c('Fibroblast','Pericyte')),identical(as.character(fm$major_celltype),as.character(fm$source_major_celltype)))
frozen<-fread(file.path(FIBRO_ROOT,'global_res012_cell_labels_scores.csv'))
stopifnot(setequal(frozen$cell_id,rownames(fm)),identical(frozen$subcluster[match(rownames(fm),frozen$cell_id)],as.character(fm$subcluster)))
excluded_v2<-fread('/home/jinshengxi/LLPS/2.1 LLPS atlas/LLPS_77_genes/fibro_pericyte_subcluster_clean_v2/excluded_C4_C5_C6_barcodes.csv')
excluded_v4<-fread('/home/jinshengxi/LLPS/2.1 LLPS atlas/LLPS_77_genes/fibro_pericyte_subcluster_clean_v4_global_noC5/excluded_clean_v2_C5_barcodes.csv')
retired<-rownames(md)[md$major_celltype%in%c('Fibroblast','Pericyte') & !rownames(md)%in%rownames(fm)]
stopifnot(setequal(retired,c(excluded_v2$cell_id,excluded_v4$cell_id)),!anyDuplicated(c(excluded_v2$cell_id,excluded_v4$cell_id)))
mapping<-c('Epithelial'='Epithelial','Endothelial'='Endothelial','Myeloid'='Myeloid','Mast'='Mast','T/Nk'='T_NK','B'='B','Plasma'='Plasma')
stopifnot(setequal(unique(md$major_celltype),c(names(mapping),'Fibroblast','Pericyte','Cycling')))
group<-unname(mapping[as.character(md$major_celltype)])
group[j]<-paste0('Fibro_',as.character(fm$subcluster))
reason<-ifelse(!is.na(group),'INCLUDED',ifelse(md$major_celltype=='Cycling','FROZEN_CYCLING_LINEAGE_UNRESOLVED','PREVIOUSLY_EXCLUDED_FROM_FROZEN_FIBRO7'))
stopifnot(!anyNA(md$orig.ident),!anyNA(md$dataset))
d<-data.table(cell=rownames(md),sample=as.character(md$orig.ident),patient_uid=NA_character_,dataset=as.character(md$dataset),major_celltype=as.character(md$major_celltype),fibro_subtype=NA_character_,cellchat_group=group,inclusion_status=reason)
d$fibro_subtype[j]<-as.character(fm$subcluster)
samples<-d[,.(patient_uid=NA_character_,dataset=unique(dataset),total_cells=.N,included_cells=sum(!is.na(cellchat_group)),excluded_cells=sum(is.na(cellchat_group))),by=sample]
stopifnot(nrow(samples)==uniqueN(d$sample))
counts<-d[!is.na(cellchat_group),.(n_cells=.N),by=.(sample,final_cellchat_group=cellchat_group)]
counts<-counts[CJ(sample=samples$sample,final_cellchat_group=GROUPS),on=.(sample,final_cellchat_group)]
counts[is.na(n_cells),n_cells:=0L]; counts[,group_order:=match(final_cellchat_group,GROUPS)];setorder(counts,sample,group_order)
counts<-merge(counts,samples[,.(sample,patient_uid,dataset)],by='sample',sort=FALSE)
elig<-merge(counts[,.(sample,source=final_cellchat_group,n_source=n_cells)],counts[,.(sample,target=final_cellchat_group,n_target=n_cells)],by='sample',allow.cartesian=TRUE,sort=FALSE)
elig[,eligible:=n_source>=30L & n_target>=30L]
definitions<-data.table(group_order=seq_along(GROUPS),cellchat_group=GROUPS,source_object=c(rep(FIBRO_OBJECT,7),rep(MAJOR_OBJECT,7)),source_field=c(rep('subcluster',7),rep('major_celltype',7)),source_value=c(paste0('C',0:6),'Epithelial','Endothelial','Myeloid','T/Nk','B','Plasma','Mast'))
write_tsv(definitions,'01_metadata/01_cellchat_group_definition.tsv')
write_tsv(counts,'01_metadata/01_sample_group_cell_counts.tsv')
write_tsv(d,'01_metadata/cellchat_cell_metadata.tsv');write_tsv(samples,'01_metadata/biological_sample_manifest.tsv')
write_tsv(d[is.na(cellchat_group)],'01_metadata/primary_excluded_cells.tsv')
write_tsv(elig,'01_metadata/sample_edge_eligibility.tsv')
coverage<-counts[,.(total_cells=sum(n_cells),n_samples_present=sum(n_cells>0),n_samples_eligible=sum(n_cells>=30),max_sample_cells=max(n_cells)),by=final_cellchat_group]
coverage<-coverage[match(GROUPS,final_cellchat_group)];write_tsv(coverage,'00_audit/group_sample_coverage.tsv')
audit<-data.table(metric=c('authoritative_major_object','authoritative_fibro7_object','Seurat_version','SeuratObject_version','CellChat_version','total_cells','biological_samples','patient_number','biological_sample_field','patient_uid_field','dataset_field','major_field','fibro_subtype_field','RNA_assay_structure','normalized_layer','normalization','scale_factor','primary_included_cells','excluded_unresolved_cycling','excluded_previous_fibro_decisions','frozen_fibro_cells','frozen_subtype_barcode_match','frozen_score_match','seed'),value=c(MAJOR_OBJECT,FIBRO_OBJECT,as.character(packageVersion('Seurat')),as.character(packageVersion('SeuratObject')),'NOT_INSTALLED',nrow(md),nrow(samples),'UNKNOWN: no patient field','orig.ident','ABSENT','dataset','major_celltype','subcluster in frozen fibro object','Assay5; counts/data dgCMatrix 71683x353623; scale.data matrix 3000x353623','RNA/data','LogNormalize',10000,sum(!is.na(group)),sum(reason=='FROZEN_CYCLING_LINEAGE_UNRESOLVED'),length(retired),nrow(fm),'PASS','PASS',123))
write_tsv(audit,'00_audit/preflight_audit.tsv')
writeLines(c('# CellChat group-definition audit','',paste0('- Authoritative full atlas: ',MAJOR_OBJECT),paste0('- Authoritative final fibro7 assignment: ',FIBRO_OBJECT),'- No existing single full-atlas object contains the final fibro7 subtype field. Exact barcode join adds cellchat_group only to a new analysis copy.','- Actual fields: sample=orig.ident; dataset=dataset; major=major_celltype; final fibro=subcluster (frozen fibro object).',paste0('- Cells=',nrow(md),'; biological samples=',nrow(samples),'; primary included=',sum(!is.na(group)),'.'),'- patient_uid and other patient identifiers are ABSENT. Patient count is unknown; long tables retain patient_uid=NA, without inferring patients from samples.',paste0('- Frozen C0–C6 cells=',nrow(fm),'; assignment equals clean_snn_res.0.12, Idents and exported frozen cell labels. Major annotation, samples, dataset and LLPS77_AUC match the parent atlas exactly.'),paste0('- Previously excluded stromal cells=',length(retired),' = ',nrow(excluded_v2),' (old C4/C5/C6) + ',nrow(excluded_v4),' (old clean-v2 C5). Exact union equals all atlas fibro/pericyte barcodes absent from final fibro7. These historical exclusions are inherited, with no new QC, no reassignment, and no generic Fibro/Pericyte group.'),paste0('- Major Cycling cells excluded=',sum(reason=='FROZEN_CYCLING_LINEAGE_UNRESOLVED'),'. Frozen annotation does not resolve lineage. Fibro C6 is retained as requested; it is distinct from excluded major Cycling.'),'- RNA input is the full atlas RNA/data LogNormalize layer; commands verify scale.factor=10000. No score/reduction/integrated input.','- CellChat is not currently installed. Version will be updated after an approved isolated installation.','- All 14 groups remain in every count/matrix framework. Counts below 30 are structurally ineligible; absence is never recoded as biological zero.','',paste0('- Group order: ',paste(GROUPS,collapse=', ')), '', '## Group coverage', '', paste(capture.output(print(coverage)),collapse='\n')),file.path(ROOT,'00_audit/01_group_definition_audit.md'))
saveRDS(list(groups=GROUPS,metadata=d,samples=samples,counts=counts,eligibility=elig,major_object=MAJOR_OBJECT,fibro_object=FIBRO_OBJECT),file.path(ROOT,'01_metadata/frozen_analysis_inputs.rds'))
